const e = $input.first().json;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
let text = `📅 <b>${esc(e.title)}</b>\n🕐 ${esc(e.label)}`;
if (e.duration_defaulted) text += ' <i>(default 1h)</i>';
if (e.location) text += `\n📍 ${esc(e.location)}`;
if (e.notes) text += `\n📝 ${esc(e.notes)}`;
return [{ json: { ...e, card: text } }];

const sent = $input.first().json;
const messageId = sent.message_id ?? sent.result?.message_id;
if (!messageId) {
  throw new Error('no message_id in Telegram response: ' + JSON.stringify(sent).slice(0, 300));
}

const d = $('Build card').first().json;
const store = $getWorkflowStaticData('global');
store.drafts = store.drafts || {};

const now = Date.now();
for (const k of Object.keys(store.drafts)) {
  if (now - store.drafts[k].created > 24 * 3600 * 1000) delete store.drafts[k];
}

store.drafts[messageId] = {
  created: now,
  title: d.title,
  start: d.start,
  end: d.end,
  location: d.location,
  notes: d.notes,
  duration_defaulted: d.duration_defaulted,
  orig: $('Telegram Trigger').first().json.message.message_id,
};

store.latest = messageId;

return [{ json: { saved: messageId, orig: store.drafts[messageId].orig, latest: store.latest, drafts_count: Object.keys(store.drafts).length } }];

const cb = $('Telegram Trigger').first().json.callback_query;
const action = cb.data;
const id = cb.message.message_id;
const store = $getWorkflowStaticData('global');
const d = store.drafts ? store.drafts[id] : undefined;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

if (!d) {
  return [{ json: {
    found: false, action, id,
    card: esc(cb.message.text || '') + '\n\n⚠️ Draft not found (expired or older than the draft store). Send the event again.',
  } }];
}

const tz = 'Europe/Amsterdam';
const s = DateTime.fromISO(d.start, { zone: tz });
const e = DateTime.fromISO(d.end, { zone: tz });

let base = `📅 <b>${esc(d.title)}</b>\n🕐 ${esc(s.setLocale('en').toFormat('ccc d LLL yyyy, HH:mm') + ' - ' + e.toFormat('HH:mm'))}`;
if (d.duration_defaulted) base += ' <i>(default 1h)</i>';
if (d.location) base += `\n📍 ${esc(d.location)}`;
if (d.notes) base += `\n📝 ${esc(d.notes)}`;
const status = action === 'add' ? '✅ Added to calendar' : '❌ Cancelled';

const icsText = t => String(t).replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\r?\n/g, '\\n');
const utc = dt => dt.toUTC().toFormat("yyyyMMdd'T'HHmmss'Z'");
const name = `n8n-${id}-${Date.now()}`;
const lines = [
  'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//n8n calendar bot//EN', 'BEGIN:VEVENT',
  `UID:${name}@<domain>`, `DTSTAMP:${utc(DateTime.now())}`,
  `DTSTART:${utc(s)}`, `DTEND:${utc(e)}`, `SUMMARY:${icsText(d.title)}`,
];
if (d.location) lines.push(`LOCATION:${icsText(d.location)}`);
if (d.notes) lines.push(`DESCRIPTION:${icsText(d.notes)}`);
lines.push('END:VEVENT', 'END:VCALENDAR', '');

delete store.drafts[id];
if (String(store.latest) === String(id)) delete store.latest;

return [{ json: {
  found: true, action, id, orig: d.orig,
  card: base + '\n\n' + status,
  card_base: base,
  ics: lines.join('\r\n'),
  ics_name: name + '.ics',
} }];

const m = $('Telegram Trigger').first().json.message;
const replyTo = m.reply_to_message.message_id;
const store = $getWorkflowStaticData('global');
const draft = store.drafts ? store.drafts[replyTo] : undefined;
const isLatest = String(store.latest) === String(replyTo);

let status;
if (!draft) status = 'closed';
else if (!isLatest) status = 'older';
else status = 'editable';

let current = null;
if (draft) {
  const tz = 'Europe/Amsterdam';
  const s = DateTime.fromISO(draft.start, { zone: tz });
  const e = DateTime.fromISO(draft.end, { zone: tz });
  current = {
    title: draft.title,
    date_kind: 'explicit',
    weekday: 'none',
    day: s.day,
    month: s.month,
    year: s.year,
    offset_amount: null,
    offset_unit: 'none',
    start_time: s.toFormat('HH:mm'),
    duration_minutes: Math.round(e.diff(s, 'minutes').minutes),
    location: draft.location ?? null,
    notes: draft.notes ?? null,
  };
}

return [{ json: { status, replyTo, text: m.text, current } }];

const r = $input.first().json;
const store = $getWorkflowStaticData('global');
store.drafts = store.drafts || {};
store.drafts[r.replyTo] = r.updated;
return [{ json: r }];

