const raw = $input.first().json.message.content;
let ev;
try { ev = JSON.parse(raw); }
catch (e) { return [{ json: { ok: false, error: 'invalid JSON from model', raw } }]; }

const tz = 'Europe/Amsterdam';
const today = DateTime.now().setZone(tz).startOf('day');
const WD = { monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5, saturday: 6, sunday: 7 };

let date = null;
switch (ev.date_kind) {
  case 'today': date = today; break;
  case 'tomorrow': date = today.plus({ days: 1 }); break;
  case 'day_after_tomorrow': date = today.plus({ days: 2 }); break;
  case 'weekday': {
    const wd = WD[ev.weekday];
    if (wd) {
      let ahead = (wd - today.weekday + 7) % 7;
      if (ahead === 0) ahead = 7;
      date = today.plus({ days: ahead });
    }
    break;
  }
  case 'explicit': {
    if (ev.day && ev.month) {
      date = DateTime.fromObject({ year: ev.year || today.year, month: ev.month, day: ev.day }, { zone: tz });
      if (!ev.year && date.isValid && date < today) date = date.plus({ years: 1 });
    }
    break;
  }
  case 'offset': {
    if (ev.offset_amount > 0 && ['days', 'weeks', 'months'].includes(ev.offset_unit)) {
      date = today.plus({ [ev.offset_unit]: ev.offset_amount });
    }
    break;
  }
}

if (!date || !date.isValid) return [{ json: { ok: false, error: 'could not resolve date', ...ev } }];

const tm = (ev.start_time || '').match(/^(\d{1,2}):(\d{2})$/);
if (!tm || +tm[1] > 23 || +tm[2] > 59) return [{ json: { ok: false, error: 'could not read time', ...ev } }];

const start = date.set({ hour: +tm[1], minute: +tm[2] });
if (start.startOf('day') < today) return [{ json: { ok: false, error: 'date is in the past', ...ev } }];

const dur = Number.isInteger(ev.duration_minutes) && ev.duration_minutes > 0 ? ev.duration_minutes : 60;
const end = start.plus({ minutes: dur });

return [{ json: {
  ok: true,
  title: ev.title,
  location: ev.location ?? null,
  notes: ev.notes ?? null,
  start: start.toFormat("yyyy-MM-dd'T'HH:mm"),
  end: end.toFormat("yyyy-MM-dd'T'HH:mm"),
  duration_minutes: dur,
  duration_defaulted: dur !== ev.duration_minutes,
  label: start.setLocale('en').toFormat('ccc d LLL yyyy, HH:mm') + ' - ' + end.toFormat('HH:mm'),
}}];

