const raw = $input.first().json.message.content;
const chk = $('Check reply').first().json;
const store = $getWorkflowStaticData('global');
const draft = store.drafts ? store.drafts[chk.replyTo] : undefined;
const fail = reason => [{ json: { ok: false, reason, replyTo: chk.replyTo } }];

if (!draft) return fail('draft gone');

let ev;
try { ev = JSON.parse(raw); } catch (e) { return fail('invalid JSON from model'); }
if (ev.understood !== true) return fail('not understood');

const tz = 'Europe/Amsterdam';
const today = DateTime.now().setZone(tz).startOf('day');
const WD = { monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5, saturday: 6, sunday: 7 };

let date = null;
switch (ev.date_kind) {
  case 'today': date = today; break;
  case 'tomorrow': date = today.plus({ days: 1 }); break;
  case 'day_after_tomorrow': date = today.plus({ days: 2 }); break;
  case 'weekday': {
    const wd = WD[ev.weekday];
    if (wd) {
      let ahead = (wd - today.weekday + 7) % 7;
      if (ahead === 0) ahead = 7;
      date = today.plus({ days: ahead });
    }
    break;
  }
  case 'explicit': {
    if (ev.day && ev.month) {
      date = DateTime.fromObject({ year: ev.year || today.year, month: ev.month, day: ev.day }, { zone: tz });
      if (!ev.year && date.isValid && date < today) date = date.plus({ years: 1 });
    }
    break;
  }
  case 'offset': {
    if (ev.offset_amount > 0 && ['days', 'weeks', 'months'].includes(ev.offset_unit)) {
      date = today.plus({ [ev.offset_unit]: ev.offset_amount });
    }
    break;
  }
}
if (!date || !date.isValid) return fail('could not resolve date');

const tm = (ev.start_time || '').match(/^(\d{1,2}):(\d{2})$/);
if (!tm || +tm[1] > 23 || +tm[2] > 59) return fail('could not read time');

const start = date.set({ hour: +tm[1], minute: +tm[2] });
if (start.startOf('day') < today) return fail('date is in the past');

const oldStart = DateTime.fromISO(draft.start, { zone: tz });
const oldEnd = DateTime.fromISO(draft.end, { zone: tz });
const oldDur = Math.round(oldEnd.diff(oldStart, 'minutes').minutes);
const dur = Number.isInteger(ev.duration_minutes) && ev.duration_minutes > 0 ? ev.duration_minutes : oldDur;
const end = start.plus({ minutes: dur });

const updated = {
  created: draft.created,
  orig: draft.orig,
  title: (ev.title || '').trim() || draft.title,
  start: start.toFormat("yyyy-MM-dd'T'HH:mm"),
  end: end.toFormat("yyyy-MM-dd'T'HH:mm"),
  location: ev.location ?? null,
  notes: ev.notes ?? null,
  duration_defaulted: !!draft.duration_defaulted && dur === oldDur,
};

const changed = ['title', 'start', 'end', 'location', 'notes']
  .some(k => updated[k] !== (draft[k] ?? null));
if (!changed) return fail('no change');

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const label = start.setLocale('en').toFormat('ccc d LLL yyyy, HH:mm') + ' - ' + end.toFormat('HH:mm');
let card = `📅 <b>${esc(updated.title)}</b>\n🕐 ${esc(label)}`;
if (updated.duration_defaulted) card += ' <i>(default 1h)</i>';
if (updated.location) card += `\n📍 ${esc(updated.location)}`;
if (updated.notes) card += `\n📝 ${esc(updated.notes)}`;

return [{ json: { ok: true, replyTo: chk.replyTo, updated, card, label } }];

